Here's a modern MSTest test class covering the key patterns:

```csharp
using System.Net;

[TestClass]
public sealed class DataFetcherTests
{
    // 1. Basic async test — just use async Task, no need for .Result or .Wait()
    [TestMethod]
    public async Task FetchAsync_ReturnsContent_OnSuccess()
    {
        var handler = new MockHttpMessageHandler("hello", HttpStatusCode.OK);
        var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        string result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("hello", result);
    }

    // 2. Testing that exceptions propagate correctly
    [TestMethod]
    public async Task FetchAsync_Throws_OnServerError()
    {
        var handler = new MockHttpMessageHandler("", HttpStatusCode.InternalServerError);
        var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExceptionAsync<HttpRequestException>(
            () => fetcher.FetchAsync("https://example.com"));
    }

    // 3. Timeout — prevents a hung test from blocking CI indefinitely
    [TestMethod]
    [Timeout(3000)] // milliseconds; test fails if it exceeds this
    public async Task FetchAsync_CompletesWithinTimeout()
    {
        var handler = new MockHttpMessageHandler("fast", HttpStatusCode.OK);
        var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        string result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("fast", result);
    }

    // 4. CancellationToken — verify the token is actually respected
    [TestMethod]
    public async Task FetchAsync_ThrowsWhenCancelled()
    {
        var handler = new MockHttpMessageHandler("data", HttpStatusCode.OK, delay: TimeSpan.FromSeconds(10));
        var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        using var cts = new CancellationTokenSource();
        cts.Cancel(); // cancel immediately

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    // 5. CancellationToken with a deadline
    [TestMethod]
    public async Task FetchAsync_ThrowsWhenDeadlineExceeded()
    {
        var handler = new MockHttpMessageHandler("slow", HttpStatusCode.OK, delay: TimeSpan.FromSeconds(10));
        var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        using var cts = new CancellationTokenSource(TimeSpan.FromMilliseconds(50));

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    // Reusable fake handler — no external mocking library needed
    private sealed class MockHttpMessageHandler : HttpMessageHandler
    {
        private readonly string _content;
        private readonly HttpStatusCode _statusCode;
        private readonly TimeSpan _delay;

        public MockHttpMessageHandler(string content, HttpStatusCode statusCode, TimeSpan delay = default)
        {
            _content = content;
            _statusCode = statusCode;
            _delay = delay;
        }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            if (_delay > TimeSpan.Zero)
                await Task.Delay(_delay, cancellationToken);

            return new HttpResponseMessage(_statusCode)
            {
                Content = new StringContent(_content)
            };
        }
    }
}
```

**Key patterns demonstrated:**

| Pattern | How |
|---|---|
| **Async tests** | Return `async Task`, not `void` — MSTest awaits properly |
| **Timeout** | `[Timeout(ms)]` fails the test if it hangs |
| **Cancellation** | Pass a pre-cancelled or deadline-based `CancellationTokenSource` |
| **Exception assertion** | `Assert.ThrowsExceptionAsync<T>()` for async throws |
| **No external deps** | Subclass `HttpMessageHandler` directly instead of pulling in a mocking library |

The `MockHttpMessageHandler` with configurable delay is what makes the cancellation tests work — `Task.Delay` forwards the token, so pre-cancelled or timed-out tokens throw `TaskCanceledException` just like a real HTTP call would.
